// Extract & normalize order data from WooCommerce webhook
const order = $input.first().json;

const customerData = {
  orderId: order.id || order.order_id,
  orderStatus: order.status,
  paymentMethod: order.payment_method,
  orderTotal: parseFloat(order.total || 0),
  currency: order.currency || 'BDT',

  // Billing info
  firstName: order.billing?.first_name || '',
  lastName: order.billing?.last_name || '',
  fullName: `${order.billing?.first_name || ''} ${order.billing?.last_name || ''}`.trim(),
  email: order.billing?.email || '',
  phone: order.billing?.phone || '',
  address: order.billing?.address_1 || '',
  city: order.billing?.city || '',
  country: order.billing?.country || 'BD',

  // Items
  items: (order.line_items || []).map(item => ({
    name: item.name,
    qty: item.quantity,
    price: parseFloat(item.price || 0)
  })),
  totalItems: (order.line_items || []).reduce((sum, i) => sum + i.quantity, 0),

  // Meta
  isCOD: order.payment_method === 'cod',
  orderDate: order.date_created || new Date().toISOString(),
  ipAddress: order.customer_ip_address || ''
};

return [{ json: customerData }];

// Data Enrichment & Validation
const data = $input.first().json;

// Phone normalization (BD format)
let phone = data.phone?.replace(/\D/g, '') || '';
if (phone.startsWith('0')) phone = '880' + phone.slice(1);
if (!phone.startsWith('880') && phone.length === 10) phone = '880' + phone;

// Validate phone
const validPhone = /^880[0-9]{10}$/.test(phone);

// Email validation
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email || '');

// Risk scoring
let riskScore = 0;
const riskFlags = [];

// COD orders = higher risk
if (data.isCOD) { riskScore += 20; riskFlags.push('COD_ORDER'); }

// High value order
if (data.orderTotal > 5000) { riskScore += 15; riskFlags.push('HIGH_VALUE'); }

// Invalid phone
if (!validPhone) { riskScore += 40; riskFlags.push('INVALID_PHONE'); }

// Invalid email
if (!validEmail) { riskScore += 25; riskFlags.push('INVALID_EMAIL'); }

// Missing address
if (!data.address || data.address.length < 5) { riskScore += 20; riskFlags.push('INCOMPLETE_ADDRESS'); }

// Very high order total with COD
if (data.isCOD && data.orderTotal > 10000) { riskScore += 30; riskFlags.push('HIGH_VALUE_COD'); }

return [{
  json: {
    ...data,
    phone,
    normalizedPhone: phone,
    validPhone,
    validEmail,
    riskScore,
    riskFlags,
    enrichedAt: new Date().toISOString()
  }
}];

// Merge fraud check result with customer data
const customer = $('Get Customer Details').first().json;
const enriched = $('Data Enrichment & Validation').first().json;
let fraudResult = {};

try {
  fraudResult = $input.first().json;
} catch(e) {
  fraudResult = { fraudScore: 0, status: 'UNKNOWN' };
}

// Combine risk scores
const fraudApiScore = fraudResult.fraudlabspro_score || fraudResult.score || 0;
const totalRisk = Math.min(100, enriched.riskScore + (fraudApiScore * 0.3));

const isFraudulent = totalRisk >= 60 
  || fraudResult.fraudlabspro_status === 'REJECT'
  || (enriched.isCOD && !enriched.validPhone);

return [{
  json: {
    ...enriched,
    fraudApiScore,
    totalRiskScore: Math.round(totalRisk),
    isFraudulent,
    fraudStatus: fraudResult.fraudlabspro_status || 'REVIEW',
    needsOTP: !isFraudulent && enriched.validPhone && enriched.isCOD,
    checkedAt: new Date().toISOString()
  }
}];

// Generate OTP and prepare WhatsApp message
const data = $input.first().json;

// Generate 6-digit OTP
const otp = Math.floor(100000 + Math.random() * 900000).toString();
const otpExpiry = new Date(Date.now() + 10 * 60 * 1000).toISOString(); // 10 min

// Format order items
const itemsList = (data.items || []).map(i => `• ${i.name} × ${i.qty}`).join('\n');

const whatsappMessage = `🛒 *Order Confirmation - OTP Required*

Dear *${data.fullName}*,

Your order *#${data.orderId}* has been received!

📦 *Order Summary:*
${itemsList}

💰 *Total: ${data.currency} ${data.orderTotal}*
📍 *Delivery: ${data.city}*

🔐 *Your OTP: ${otp}*
⏱ Valid for 10 minutes only

Reply with this OTP to confirm your order. If you did not place this order, please ignore.

_Powered by AutoVerify_`;

return [{
  json: {
    ...data,
    otp,
    otpExpiry,
    whatsappMessage,
    whatsappPhone: `+${data.normalizedPhone}`,
    channel: 'whatsapp'
  }
}];

// Flag fraudulent order for manual review
const data = $input.first().json;

const reviewNote = {
  orderId: data.orderId,
  customer: data.fullName,
  phone: data.normalizedPhone,
  email: data.email,
  orderTotal: `${data.currency} ${data.orderTotal}`,
  riskScore: data.totalRiskScore,
  riskFlags: (data.riskFlags || []).join(', '),
  fraudStatus: data.fraudStatus,
  isCOD: data.isCOD,
  flaggedAt: new Date().toISOString(),
  action: 'MANUAL_REVIEW_REQUIRED'
};

console.log('🚨 Flagged for review:', JSON.stringify(reviewNote));

// Update WooCommerce order status to on-hold
return [{ json: { ...data, reviewNote, orderFlagged: true } }];

