// Verify & normalize phone for SMS
const data = $('Data Enrichment & Validation').first().json;

const phone = data.normalizedPhone;
const isValid = data.validPhone;

if (!isValid) {
  throw new Error(`Invalid phone number: ${phone} for order #${data.orderId}`);
}

// Generate OTP for SMS (same or new depending on flow)
const otp = Math.floor(100000 + Math.random() * 900000).toString();
const otpExpiry = new Date(Date.now() + 10 * 60 * 1000).toISOString();

return [{
  json: {
    ...data,
    otp,
    otpExpiry,
    smsPhone: phone,
    phoneVerified: true
  }
}];

// Prepare SMS body
const data = $input.first().json;

const smsBody = `[${data.orderId}] OTP: ${data.otp}. Confirm your COD order of ${data.currency} ${data.orderTotal}. Valid 10 mins. Do not share. -AutoVerify`;

return [{
  json: {
    ...data,
    smsBody,
    smsTo: data.smsPhone,
    smsPreparedAt: new Date().toISOString()
  }
}];

// Store OTP in database / cache for verification
// Using n8n's built-in static data or external Redis
const whatsappData = $('Generate WhatsApp Message').first()?.json || {};
const smsData = $('Verify Phone Number').first()?.json || {};

const otpRecord = {
  orderId: whatsappData.orderId || smsData.orderId,
  phone: whatsappData.normalizedPhone || smsData.normalizedPhone,
  otp: whatsappData.otp || smsData.otp,
  otpExpiry: whatsappData.otpExpiry || smsData.otpExpiry,
  channels: ['whatsapp', 'sms'],
  status: 'PENDING',
  attempts: 0,
  createdAt: new Date().toISOString()
};

// In production: store in Redis/DB
// await $redis.set(`otp:${otpRecord.orderId}`, JSON.stringify(otpRecord), 'EX', 600);

console.log('OTP Record saved:', JSON.stringify(otpRecord));
return [{ json: otpRecord }];

// Verify OTP submitted by customer
const body = $input.first().json;
const { orderId, otp: submittedOtp } = body;

// In production: fetch from Redis/DB
// const record = JSON.parse(await $redis.get(`otp:${orderId}`));

// Mock DB check (replace with real DB fetch)
const mockRecord = {
  otp: body.expectedOtp || '123456',
  otpExpiry: new Date(Date.now() + 5 * 60 * 1000).toISOString(),
  attempts: 0
};

const now = new Date();
const isExpired = new Date(mockRecord.otpExpiry) < now;
const isMatch = mockRecord.otp === submittedOtp;
const maxAttempts = mockRecord.attempts >= 3;

let verificationResult;
if (isExpired) {
  verificationResult = { success: false, reason: 'OTP_EXPIRED', orderId };
} else if (maxAttempts) {
  verificationResult = { success: false, reason: 'MAX_ATTEMPTS_EXCEEDED', orderId };
} else if (!isMatch) {
  verificationResult = { success: false, reason: 'INVALID_OTP', orderId, attempts: mockRecord.attempts + 1 };
} else {
  verificationResult = { success: true, reason: 'VERIFIED', orderId, verifiedAt: now.toISOString() };
}

return [{ json: verificationResult }];
